def acyclic(edges):
    nodes = {n for e in edges for n in e}
    color = {}
    def dfs(u):
        color[u] = 1
        for (a, b) in edges:
            if a == u:
                if color.get(b) == 1: return False
                if color.get(b) is None and not dfs(b): return False
        color[u] = 2
        return True
    return all(color.get(n) is not None or dfs(n) for n in nodes)

def topo(edges, nodes):
    order, seen = [], set()
    while len(order) < len(nodes):
        for n in sorted(nodes):
            if n not in seen and all(a in seen or a == n for (a, b) in edges if b == n):
                order.append(n); seen.add(n); break
        else:
            return None
    return order

