def two_phase_ok(ops):
    """각 트랜잭션이 잠금을 모두 얻은 뒤에야 풀 수 있는지."""
    txns = {t for _, t, _ in ops}
    for T in txns:
        acq, rel = [], []
        items = {x for _, t, x in ops if t == T}
        for x in items:
            idx = [i for i, (k, t, y) in enumerate(ops) if t == T and y == x]
            acq.append(idx[0])
            # 마지막 접근 이후 다른 트랜잭션의 충돌 연산 = 반납 마감시한
            mine = {ops[i][0] for i in idx}
            dl = [j for j, (k, t, y) in enumerate(ops)
                  if j > idx[-1] and t != T and y == x and not (k == "r" and mine == {"r"})]
            rel.append(dl[0] if dl else len(ops))
        if max(acq) > min(rel):
            return False
    return True

