class DB:
    def __init__(self, v): self.committed = v; self.history = [v]; self.buf = {}
    def write(self, t, v): self.buf[t] = v
    def commit(self, t):
        if t in self.buf:
            self.committed = self.buf.pop(t); self.history.append(self.committed)
    def abort(self, t): self.buf.pop(t, None)
    def read(self, t, level):
        if level == "READ UNCOMMITTED":
            other = [v for k, v in self.buf.items() if k != t]
            return other[-1] if other else self.committed
        return self.committed          # READ COMMITTED 이상

def run(level):
    db = DB(100)
    db.write("T1", 150)      # T1: UPDATE balance = 150 (미커밋)
    seen = db.read("T2", level)
    db.abort("T1")           # T1 롤백
    return seen, db.history

