class Store:
    def __init__(self):
        self.rows = {1: [(0, 10)]}   # id -> [(commit_ts, value)]
        self.ts = 0
    def commit_update(self, rid, v):
        self.ts += 1; self.rows.setdefault(rid, []).append((self.ts, v))
    def commit_insert(self, rid, v):
        self.ts += 1; self.rows[rid] = [(self.ts, v)]
    def read(self, rid, snap):
        vs = [v for t, v in self.rows.get(rid, []) if t <= snap]
        return vs[-1] if vs else None
    def scan(self, snap):
        return [r for r in self.rows if self.read(r, snap) is not None]

def run(level):
    s = Store(); start = s.ts
    snap = lambda: s.ts if level == "RC" else start   # RC=문장 스냅샷, RR=트랜잭션 스냅샷
    v1, c1 = s.read(1, snap()), len(s.scan(snap()))
    s.commit_update(1, 20)      # 다른 트랜잭션이 UPDATE 후 커밋
    s.commit_insert(2, 99)      # 다른 트랜잭션이 INSERT 후 커밋
    v2, c2 = s.read(1, snap()), len(s.scan(snap()))
    return (v1, v2), (c1, c2)

