class LockMgr:
    def __init__(self): self.owner = {}; self.wait = {}
    def acquire(self, t, x):
        o = self.owner.get(x)
        if o is None or o == t:
            self.owner[x] = t; self.wait.pop(t, None); return "ok"
        self.wait[t] = o
        return "cycle" if self.detect() else "wait"
    def detect(self):
        for s in list(self.wait):
            seen, cur = set(), s
            while cur in self.wait:
                cur = self.wait[cur]
                if cur in seen or cur == s: return True
                seen.add(cur)
        return False

